package com.ridelink.drivervehicle.dto;
import com.ridelink.drivervehicle.domain.Availability; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.time.Instant;
public final class DriverDtos { private DriverDtos(){} public record VehicleRequest(@NotBlank String make,@NotBlank String model,@NotBlank String plateNumber,@Min(1) @Max(12) int capacity){} public record ProfileRequest(@NotBlank String userId,@NotBlank String licenseNumber,@NotNull @Valid VehicleRequest vehicle,@NotBlank String serviceZone){} public record AvailabilityRequest(@NotNull Availability availability){} public record LocationRequest(@NotNull @DecimalMin("-90") @DecimalMax("90") Double latitude,@NotNull @DecimalMin("-180") @DecimalMax("180") Double longitude,@NotBlank String zone){} public record VehicleResponse(String make,String model,String plateNumber,int capacity){} public record DriverResponse(String id,String userId,String licenseNumber,Availability availability,String serviceZone,Double latitude,Double longitude,VehicleResponse vehicle,Instant createdAt){} }
